#!/usr/bin/env bash
# ntnlab on ns-3-NTN v1.1.0 (nr-ntn-dev v1.1.0 in contrib/nr), version of 25 October 2026 (several
# beams and satellites in ntnlab_nr: --beams, --beamReuse, --satellites, --geometryOnly and the
# rest; the buffer status report with its triggers, --bsr=standard; the uplink PF ranking by the
# worth of the next resource block group, --ulPfMarginal; before: the review of the uplink with
# PUSCH repetition, --puschMinBlockBytes, --ulSinrAvgMs, --ulPolarizationLossDb, the closed-loop
# options, NTN-TDL speed and delay spread, the PDCCH power boost, --sinrTrace, the scheduler test
# pftest, ROHC fallback to U-mode, every UE in the results, --fadingHoldMs, --ueBufferAgeS, shorter
# passes, the SNR tables by elevation, the downlink PFD limit, wide uplink grants, the size and
# level of each DCI of the cell, call control, configured grants with repetitions, the EESM-IR
# error model at low SNR). One file: everything it installs is inside it.
#
#   bash ntnlab_install.sh [NS3_DIR]
#
#   NS3_DIR  the ns-3 directory, the one with ./ns3 and contrib/nr (default: the current one)
#
# It works on any tree of ns-3-NTN v1.1.0, with no ntnlab or with an earlier version of it
# (patched, unpacked, or installed by this script before). It puts in the new version of each
# of its 70 files that differs (contrib/nr, scratch/ntnlab_nr.cc, scratch/pdcchtest.cc and the
# scripts in NS3_DIR), saves the files it replaces in NS3_DIR/ntnlab-backup-<date>.tgz first,
# and leaves files that are already right alone, so the build compiles only what changed. At
# the end it compares every file of contrib/nr with the tree this version was tested with.
#
# The ROHC library is needed for header compression (without it everything still builds and
# runs, with "ROHC off" in the first lines of the output):
#     sudo apt install build-essential autoconf automake libtool pkg-config
#     git clone https://github.com/didier-barvaux/rohc.git
#     cd rohc && autoreconf -fi && ./configure --disable-examples && make
#     sudo make install && sudo ldconfig && cd ..
# Then, in NS3_DIR:
#     ./ns3 configure --enable-examples --enable-modules=nr     ("nr: ROHC library found")
#     ./ns3 build
#     ./ns3 run ntnlab_nr
# To go back: tar xzf ntnlab-backup-<date>.tgz in NS3_DIR (files that were new are not in it).

set -euo pipefail

ns3dir=${1:-.}
self=$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)/$(basename "${BASH_SOURCE[0]}")

die() {
    echo "error: $*" >&2
    exit 1
}

for p in tar md5sum base64 awk; do
    command -v $p >/dev/null || die "the program $p is missing (sudo apt install $p)"
done
ns3dir=$(cd "$ns3dir" 2>/dev/null && pwd) || die "no folder $ns3dir"
cd "$ns3dir"
[ -f ns3 ] && [ -f contrib/nr/CMakeLists.txt ] ||
    die "$ns3dir is not an ns-3 directory with contrib/nr (run it from there, or give the path)"

# A tree checked out on Windows can have CR LF line ends; nothing here fits it.
if grep -q $'\r' contrib/nr/model/nr-pdcp.cc; then
    die "the files of $ns3dir have CR LF line ends (a Windows checkout). Clone again inside" \
        "Linux/WSL, or with git config core.autocrlf false, then run this again."
fi

# The files of this version, from the end of this script
tmp=$(mktemp -d)
trap 'rm -rf "$tmp"' EXIT
awk 'found { print } /^__NTNLAB_FILES_BELOW__$/ { found = 1 }' "$self" | base64 -d |
    tar xz -C "$tmp" 2>/dev/null || die "$self is damaged (its files cannot be unpacked)"
(cd "$tmp" && md5sum -c --quiet MANIFEST.md5 >/dev/null 2>&1) ||
    die "$self is damaged (its files do not match their MANIFEST.md5)"

# Every file of contrib/nr against the tested tree
check_tree() {
    local bad n
    bad=$(md5sum -c --quiet "$tmp/CHECK.md5" 2>/dev/null | sed -n 's/: FAILED.*$//p' || true)
    n=$(wc -l <"$tmp/CHECK.md5")
    if [ -z "$bad" ]; then
        echo "Checked: the $n files of contrib/nr are those of the tested tree."
    else
        echo "Note: these files of contrib/nr differ from the tested tree (your own changes, or"
        echo "not nr-ntn-dev v1.1.0 underneath):"
        echo "$bad" | sed 's/^/  /'
    fi
}

mapfile -t files < <(md5sum -c "$tmp/MANIFEST.md5" 2>/dev/null | sed -n 's/: FAILED.*$//p')
if [ ${#files[@]} -eq 0 ]; then
    echo "This version is already in $ns3dir: nothing to do."
    check_tree
    exit 0
fi
echo "Putting in the new version of ${#files[@]} files"
existing=()
for f in "${files[@]}"; do
    if [ -e "$f" ]; then
        existing+=("$f")
    fi
done
if [ ${#existing[@]} -gt 0 ]; then
    backup="ntnlab-backup-$(date +%Y%m%d-%H%M%S).tgz"
    tar czf "$backup" "${existing[@]}"
    echo "Saved the ${#existing[@]} files it replaces in $ns3dir/$backup"
fi
for f in "${files[@]}"; do
    echo "  $f"
    mkdir -p "$(dirname "$f")"
    # (a plain copy: the file gets the time of now, so the build sees it as changed)
    cp "$tmp/$f" "$f"
done
md5sum -c --quiet "$tmp/MANIFEST.md5" >/dev/null 2>&1 || die "copying the files failed"
check_tree
echo "Done. Next:"
echo "  ./ns3 configure --enable-examples --enable-modules=nr"
echo "  ./ns3 build"
echo "  ./ns3 run ntnlab_nr"
exit 0
